'use strict';
let selectedProvider='netease',visualMode=read('visualMode','flow'),themeIndex=read('themeIndex',0),lyricRows=[],lyricTranslations=[],lyricIndex=-2,lyricRequest=0,stageTrackId='',lyricOverrides=read('lyricOverrides',{}),manualPalette=false;
const palettes=[['#254449','#526d5e','#bab590'],['#313951','#655b78','#b49b91'],['#4d3834','#9a664a','#c5b690'],['#1e343f','#425d75','#81adb1']];let stagePalette=palettes[themeIndex%palettes.length];
function setVisual(mode){visualMode=['flow','type','orbit'].includes(mode)?mode:'flow';$('#stage').dataset.style=visualMode;$('#lyricsPanel').classList.toggle('type-mode',visualMode==='type');$$('[data-visual]').forEach(b=>b.classList.toggle('selected',b.dataset.visual===visualMode));save('visualMode',visualMode);lyricIndex=-2}
$$('[data-visual]').forEach(b=>b.onclick=()=>setVisual(b.dataset.visual));setVisual(visualMode);
$('#immersive').onclick=()=>window.togglePureMusic?.();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('pure-mode'))window.togglePureMusic(false)});
$('#stageTheme').onclick=()=>{themeIndex=(themeIndex+1)%palettes.length;stagePalette=palettes[themeIndex];manualPalette=true;save('themeIndex',themeIndex);toast('已切换背景配色')};
function trackCover(t){if(t.id.startsWith('demo-'))return 'covers/soundisle/'+({focus:'focus',relax:'rest',energy:'workout',sleep:'sleep'})[scene]+'.jpg';try{return MusicSources.secureUrl(MusicSources.getCover(t))||'covers/'+(t.id==='demo-tide'?'tide':t.id==='demo-orbit'?'orbit':'breathe')+'.svg'}catch{return 'covers/breathe.svg'}}
function extractPalette(url){if(manualPalette)return;const track=stageTrackId;const image=new Image();image.crossOrigin='anonymous';image.onload=()=>{if(stageTrackId!==track)return;try{const c=document.createElement('canvas');c.width=c.height=12;const g=c.getContext('2d',{willReadFrequently:true});g.drawImage(image,0,0,12,12);const d=g.getImageData(0,0,12,12).data;let chunks=[[],[],[]];for(let i=0;i<d.length;i+=4){const max=Math.max(d[i],d[i+1],d[i+2]);if(max>25&&max<245)chunks[Math.floor(i/4)%3].push([d[i],d[i+1],d[i+2]])}const next=chunks.map((arr,j)=>arr.length?'rgb('+[0,1,2].map(k=>Math.round(arr.reduce((a,b)=>a+b[k],0)/arr.length)).join(',')+')':stagePalette[j]);stagePalette=next}catch{/* A non-CORS cover still displays; use the selected palette. */}};image.src=url}
async function refreshStage(){const changed=stageTrackId!==current.id;if(!changed)return;stageTrackId=current.id;manualPalette=false;const url=trackCover(current);$('#coverImage').src=url;$('#coverImage').alt=current.title+' · 音轨封面';$('#stageTitle').textContent=current.title;$('#stageArtist').textContent=current.artist;$('#stageSourceName').textContent=current.source;extractPalette(url);await loadStageLyrics()}
$('#coverImage').onerror=()=>{if(!$('#coverImage').src.endsWith('/covers/breathe.svg'))$('#coverImage').src='covers/breathe.svg'};
async function loadStageLyrics(){const request=++lyricRequest,id=current.id;lyricRows=[];lyricTranslations=[];lyricIndex=-2;$('#lyricStatus').textContent='正在寻找歌词…';$('#lyricLines').innerHTML='<div class="instrument-title">'+esc(current.title)+'</div><p class="instrument-sub">让声音，慢慢展开。</p>';try{const override=lyricOverrides[id];const result=override||await MusicSources.getLyrics(current);if(request!==lyricRequest||id!==current.id)return;lyricRows=MusicSources.parseLyrics(result.text||'',result.format||'lrc');lyricTranslations=MusicSources.parseLyrics(result.translation||'');$('#lyricStatus').textContent=lyricRows.length?(lyricRows.some(l=>l.words.length)?'逐词同步 · YRC':'逐行同步 · LRC'):(current.id.startsWith('demo-')?'器乐声场 · 无歌词':'暂无同步歌词');$('#lyricNote').textContent=lyricRows.length?'点击歌词可跳转播放 · '+(override?'本机导入':'音乐服务提供'):'可以导入 LRC / YRC 歌词，与音乐一同流动';if(!lyricRows.length){$('#lyricLines').innerHTML='<div class="instrument-title">'+esc(current.title)+'</div><p class="instrument-sub">'+(current.id.startsWith('demo-')?'纯音乐，让思绪自由流动。':'还没有这首歌的时间轴。')+'</p>'}else renderLyricWindow()}catch(e){if(request!==lyricRequest)return;$('#lyricStatus').textContent='歌词暂不可用';$('#lyricNote').textContent=e.message+' · 可导入本地歌词'}}
function renderLyricWindow(){const index=MusicSources.atTime(lyricRows,audio.currentTime);if(index===lyricIndex)return;lyricIndex=index;$('#lyricLines').innerHTML=lyricRows.map((line,i)=>{const translation=lyricTranslations.find(t=>Math.abs(t.start-line.start)<.3)?.text;return `<button class="lyric-line ${i===index?'is-current':''}" data-line="${i}"><span>${line.words.length?line.words.map((w,k)=>`<span class="lyric-word" data-word="${k}">${esc(w.text)}</span>`).join(''):esc(line.text)}${translation?'<small>'+esc(translation)+'</small>':''}</span><span class="line-time">${fmt(line.start)}</span></button>`}).join('');$$('[data-line]').forEach(b=>b.onclick=()=>{audio.currentTime=Math.max(0,lyricRows[+b.dataset.line].start);if(audio.paused)startPlay()});const active=$('#lyricLines .is-current'),container=$('#lyricWindow');if(active){const top=active.offsetTop-container.clientHeight*.4;container.scrollTo({top:Math.max(0,top),behavior:prefs.lowMotion?'auto':'smooth'})}}
function updateLyricWords(){if(!lyricRows.length)return;renderLyricWindow();const row=lyricRows[lyricIndex];if(!row?.words?.length)return;$$('.is-current .lyric-word').forEach((el,i)=>{const w=row.words[i];if(!w)return;const percent=Math.max(0,Math.min(100,(audio.currentTime-w.start)/(w.end-w.start||.1)*100));el.style.setProperty('--sung',percent+'%')})}
window.addEventListener('sonora:track',refreshStage);document.addEventListener('sonora:lyrics',()=>{page('home');$('#lyricsPanel').scrollIntoView({behavior:prefs.lowMotion?'auto':'smooth',block:'start'})});
$('#importLyrics').onclick=()=>{modal('为当前歌曲添加同步歌词',`<p class="muted">当前歌曲：${esc(current.title)}。可选择文件，也可粘贴带时间轴的歌词。</p><textarea id="pasteLyrics" rows="7" style="width:100%;resize:vertical" placeholder="[00:01.00]第一句歌词"></textarea><select id="pasteFormat"><option value="lrc">LRC 逐行歌词</option><option value="yrc">YRC 逐词歌词</option></select><div><button class="primary" id="savePastedLyrics">保存并同步</button><button class="secondary" id="chooseLyricFile">选择文件</button></div><button class="text-button" id="resetLyrics" style="margin-top:15px">清除本曲导入歌词，恢复来源歌词</button>`);$('#chooseLyricFile').onclick=()=>$('#lyricFile').click();$('#savePastedLyrics').onclick=async()=>{const text=$('#pasteLyrics').value,format=$('#pasteFormat').value;if(!MusicSources.parseLyrics(text,format).length)return toast('未找到有效的歌词时间轴');lyricOverrides[current.id]={text,format};save('lyricOverrides',lyricOverrides);$('#dialog').close();await loadStageLyrics();toast('歌词已保存并开始同步')};$('#resetLyrics').onclick=async()=>{delete lyricOverrides[current.id];save('lyricOverrides',lyricOverrides);$('#dialog').close();await loadStageLyrics();toast('已恢复来源歌词')}};$('#lyricFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>512000){toast('歌词文件请小于 500 KB');e.target.value='';return}const text=await f.text(),format=/\.yrc$/i.test(f.name)?'yrc':'lrc';if(!MusicSources.parseLyrics(text,format).length){toast('未找到有效时间轴，请使用带时间标签的 LRC / YRC');e.target.value='';return}lyricOverrides[current.id]={text,format};save('lyricOverrides',lyricOverrides);await loadStageLyrics();e.target.value='';toast('歌词已与当前歌曲关联并保存到本机')};
$('#stageSource').onclick=()=>page('library');$('#manageSources').onclick=()=>sourceManager(selectedProvider);$('#sourceConnect').onclick=()=>sourceManager(selectedProvider);
function setProvider(p){selectedProvider=p;$$('[data-provider]').forEach(b=>b.classList.toggle('selected',b.dataset.provider===p));$('#cloudQuery').placeholder='搜索'+MusicSources.names[p]+'歌曲、歌手';$('#sourceHint').textContent=MusicSources.names[p]+' · '+(MusicSources.getConfig(p)?'服务地址已配置；搜索或验证以检查可用性。':'尚未连接自己的音乐服务。');$('#cloudResults').innerHTML=''}
$$('[data-provider]').forEach(b=>b.onclick=()=>setProvider(b.dataset.provider));setProvider(selectedProvider);
function addOnlineTracks(tracks){let count=0;for(const t of tracks){const existing=cloudTracks.find(x=>x.id===t.id||x.provider===t.provider&&x.mediaId===t.mediaId);if(existing)Object.assign(existing,t);else{cloudTracks.push(t);count++}}save('cloudTracks',cloudTracks);render();return count}
$('#cloudSearch').onclick=async()=>{const query=$('#cloudQuery').value.trim();if(!query)return toast('请输入歌名或歌手');const b=$('#cloudSearch'),provider=selectedProvider;b.disabled=true;b.textContent='搜索中';try{const tracks=await MusicSources.search(provider,query);if(selectedProvider!==provider)return;$('#sourceHint').textContent=MusicSources.names[provider]+' · 找到 '+tracks.length+' 首';$('#cloudResults').innerHTML=tracks.length?'<div class="search-result-title">搜索结果 <span>播放权限由音乐服务与账号决定</span></div>'+tracks.map((t,i)=>`<div class="track search-track"><button class="track-art" data-result-play="${i}" aria-label="播放 ${esc(t.title)}">${t.cover?'<img src="'+esc(t.cover)+'" alt="" loading="lazy">':'♫'}</button><button class="track-info" data-result-play="${i}"><b>${esc(t.title)}</b><small>${esc(t.artist)} · ${esc(t.source)}</small></button><span class="track-time">${fmt(t.duration)}</span><button class="secondary" data-result-add="${i}" aria-label="收藏到音乐库 ${esc(t.title)}">＋</button></div>`).join(''):'<div class="empty">没有找到匹配的歌曲。</div>';$$('[data-result-add]').forEach(btn=>btn.onclick=()=>{addOnlineTracks([tracks[+btn.dataset.resultAdd]]);toast('已加入音乐库')});$$('[data-result-play]').forEach(btn=>btn.onclick=async()=>{const t=tracks[+btn.dataset.resultPlay];addOnlineTracks([t]);queue=tracks;queuePos=tracks.indexOf(t);await loadTrack(t,true)})}catch(e){$('#sourceHint').textContent='连接未成功 · '+e.message;toast(e.message)}finally{b.disabled=false;b.textContent='搜索'}};$('#cloudQuery').onkeydown=e=>{if(e.key==='Enter')$('#cloudSearch').click()};
function listPicker(items,title){modal(title,items.length?items.map((x,i)=>`<div class="queue-item"><button data-list-id="${i}">${esc(x.name)}<small>${x.trackCount??''} 首</small></button></div>`).join(''):'<p class="muted">暂时没有可访问的歌单。</p>');$$('[data-list-id]').forEach(b=>b.onclick=()=>importPlaylist('netease',String(items[+b.dataset.listId].id)))}
async function importPlaylist(p,id){$('#dialogBody').innerHTML='<p class="muted">正在读取歌单…</p>';try{const tracks=await MusicSources.playlist(p,id);const n=addOnlineTracks(tracks);$('#dialog').close();toast(`读取 ${tracks.length} 首，新增 ${n} 首到音乐库`)}catch(e){$('#dialogBody').innerHTML='<p>'+esc(e.message)+'</p><p class="muted">请检查歌单是否公开、账号权限和服务状态。</p>'}}
$('#playlistImport').onclick=()=>{const p=selectedProvider;if(p==='kugou')return toast('酷狗当前支持搜索与播放，歌单导入待适配');modal('导入'+MusicSources.names[p]+'歌单',`<form id="playlistForm"><label>歌单 ID 或分享链接<input id="playlistId" required placeholder="粘贴歌单链接，或输入 ID"></label><button class="primary">读取并加入音乐库</button></form><p class="muted small">网易云单次最多读取 1000 首。私密歌单需要账号权限。</p>`);$('#playlistForm').onsubmit=e=>{e.preventDefault();let id=$('#playlistId').value.trim();if(/^https?:/i.test(id)){try{const u=new URL(id),fragment=u.hash.match(/[?&]id=(\d+)/);id=u.searchParams.get('id')||fragment?.[1]||u.pathname.split('/').filter(Boolean).pop()}catch{return toast('链接格式不正确')}}if(!id||!/^[a-zA-Z0-9_-]+$/.test(id))return toast('请输入正确的歌单 ID');importPlaylist(p,id)}};
let qrGeneration=0;
function sourceManager(p){const spec={netease:['NeteaseCloudMusicApiEnhanced','https://github.com/NeteaseCloudMusicApiEnhanced/api-enhanced'],qq:['qq-music-api 3.3.3+','https://github.com/yakult-green-tea/qq-music-api'],kugou:['KuGouMusicApi','https://github.com/MakcRe/KuGouMusicApi'],navidrome:['Navidrome / Subsonic','https://www.navidrome.org/']};qrGeneration++;modal('音乐源 · 连接与账号',`<div class="source-dialog-tabs">${Object.keys(MusicSources.names).map(k=>`<button class="${k===p?'selected':''}" data-manage="${k}">${MusicSources.names[k]}</button>`).join('')}</div><p class="muted">连接你自己的 <a href="${spec[p][1]}" target="_blank" rel="noreferrer">${spec[p][0]}</a> 服务。网页版与 Folia 一样需要可用的后端实例，服务地址不包含账号密码。</p><label>服务地址<input id="providerUrl" type="url" value="${esc(MusicSources.getConfig(p)?.endpoint||'')}" placeholder="https://your-music-api.example"></label>${p==='navidrome'?'<label>用户名<input id="navUser" autocomplete="off"></label><label>密码（仅当前会话）<input id="navPassword" type="password" autocomplete="off"></label>':''}<div class="source-connection-actions"><button class="primary" id="verifySource">保存并验证</button>${['netease','qq'].includes(p)?'<button class="secondary" id="qrLogin">扫码登录</button>':''}<button class="text-button" id="logoutSource">退出当前会话</button></div><p id="connectionResult" class="connection-result">${MusicSources.getConfig(p)?'地址已保存，尚未验证本次连接。':'尚未配置'}</p>${p==='netease'?'<div class="account-actions"><button class="secondary" id="myPlaylists">我的歌单</button><button class="secondary" id="dailySongs">每日推荐</button></div>':''}<div id="qrArea"></div><p class="muted small">扫码登录态和密码不落盘，刷新页面后需要重新登录。服务必须支持当前网页的跨域访问；不要把账号连接到不信任的公共实例。</p><div class="source-limit-note">${p==='qq'?'QQ 接口需支持 X-QQ-Session 跨域请求；歌词暂可通过本地 LRC / YRC 导入。':p==='kugou'?'酷狗搜索、播放、LRC 歌词已适配；账号扫码与私有歌单待适配。':p==='navidrome'?'使用 Subsonic 令牌认证，支持搜索、串流、封面和歌单；歌词可本地导入。':'支持 Enhanced API 扫码、搜索、歌单、播放、LRC / YRC 同步歌词。'}</div>`);$$('[data-manage]').forEach(b=>b.onclick=()=>sourceManager(b.dataset.manage));const configure=()=>{MusicSources.configure(p,$('#providerUrl').value.trim());if(p==='navidrome')MusicSources.navLogin($('#navUser').value.trim(),$('#navPassword').value);if(p==='netease')$('#musicEndpoint').value=$('#providerUrl').value.trim();setProvider(p)};$('#verifySource').onclick=async()=>{const b=$('#verifySource');b.disabled=true;try{configure();$('#connectionResult').textContent='正在验证…';const result=await MusicSources.test(p);if($('#connectionResult'))$('#connectionResult').textContent=result;$('#musicStatus').textContent=MusicSources.names[p]+' · '+result}catch(e){if($('#connectionResult'))$('#connectionResult').textContent='验证失败：'+e.message}finally{b.disabled=false}};$('#logoutSource').onclick=()=>{MusicSources.logout(p);qrGeneration++;$('#connectionResult').textContent='当前页面会话已清除';$('#qrArea').innerHTML=''};if($('#qrLogin'))$('#qrLogin').onclick=async()=>{try{configure();const generation=++qrGeneration;$('#qrArea').innerHTML='<p class="muted">正在生成二维码…</p>';const qr=await MusicSources.qrStart(p);if(generation!==qrGeneration||!$('#qrArea'))return;$('#qrArea').innerHTML='<div class="qr-card"><img src="'+esc(qr.image)+'" alt="使用'+MusicSources.names[p]+' App 扫码登录"><p id="qrStatus">请使用音乐 App 扫码，并在手机上确认</p></div>';let attempts=0;const poll=async()=>{if(generation!==qrGeneration||!$('#dialog').open||!$('#qrStatus'))return;if(attempts++>=80){$('#qrStatus').textContent='二维码已过期，请重新生成';return}try{const status=await MusicSources.qrCheck(p,qr.key);if(generation!==qrGeneration||!$('#qrStatus'))return;if(status.loggedIn){$('#qrStatus').textContent='登录成功，可读取歌单与播放';$('#connectionResult').textContent='已登录';$('#musicStatus').textContent=MusicSources.names[p]+' · 已登录';qrGeneration++;return}if(status.code===800){$('#qrStatus').textContent='二维码已失效，请重新生成';return}$('#qrStatus').textContent=status.code===802?'已扫码，请在手机上确认':'等待扫码…';setTimeout(poll,2500)}catch(e){if($('#qrStatus'))$('#qrStatus').textContent='登录检查失败：'+e.message}};setTimeout(poll,2500)}catch(e){if($('#qrArea'))$('#qrArea').textContent='二维码生成失败：'+e.message}};if(p==='netease'){$('#myPlaylists').onclick=async()=>{try{const d=await MusicSources.request(p,'/login/status'),uid=d.data?.profile?.userId;if(!uid)throw Error('请先扫码登录网易云账号');const lists=await MusicSources.request(p,'/user/playlist',{uid,limit:100});listPicker(lists.playlist||[],'我的网易云歌单')}catch(e){toast(e.message)}};$('#dailySongs').onclick=async()=>{try{const d=await MusicSources.request(p,'/recommend/songs'),ts=(d.data?.dailySongs||[]).map(s=>MusicSources.normalize(p,s));if(!ts.length)throw Error('未取得推荐，请先登录');const count=addOnlineTracks(ts);$('#dialog').close();toast('已加入 '+count+' 首每日推荐')}catch(e){toast(e.message)}}}}
const back=$('#stageBackground'),bg=back.getContext('2d');let stageFrame=0;function stageDraw(){requestAnimationFrame(stageDraw);if(document.hidden||$('#home').classList.contains('hidden'))return;stageFrame++;if(stageFrame%2)return;back.width=160;back.height=120;const glow=bg.createRadialGradient(80,55,5,80,55,90);glow.addColorStop(0,getComputedStyle(document.documentElement).getPropertyValue('--scene-accent').trim()||'#e0a96d');glow.addColorStop(1,'transparent');bg.clearRect(0,0,160,120);bg.fillStyle=glow;bg.fillRect(0,0,160,120);$('#stageClock').textContent=fmt(audio.currentTime);updateLyricWords()}stageDraw();refreshStage();

$('#heroPlay').onclick=()=>audio.paused?startPlay():audio.pause();audio.addEventListener('play',()=>$('#heroPlay').innerHTML='Ⅱ 暂停聆听 <span>↗</span>');audio.addEventListener('pause',()=>$('#heroPlay').innerHTML='▶ 继续聆听 <span>↗</span>');
